supabase = create_client(SUPABASE_URL, SUPABASE_ANON_KEY) if SUPABASE_URL and SUPABASE_ANON_KEY else None

cookies = EncryptedCookieManager(prefix=f"{APP_ID}_", password=COOKIE_PASSWORD)
if not cookies.ready():
    st.stop()

# ============================================================
# ✅ Login persistence (refresh-safe best effort)
# ============================================================
def _best_effort_refresh_with_rt(refresh_token: str) -> dict | None:
    if not supabase or not refresh_token:
        return None
    auth = supabase.auth
    # Try common method names across supabase-py versions
    for name in ("refresh_session", "refresh_token", "set_session"):
        fn = getattr(auth, name, None)
        if not callable(fn):
            continue
        try:
            # Try different calling conventions
            try:
                res = fn(refresh_token)
            except TypeError:
                res = fn({"refresh_token": refresh_token})
            # Normalize
            session = getattr(res, "session", None) or (res.get("session") if isinstance(res, dict) else None)
            user = getattr(res, "user", None) or (res.get("user") if isinstance(res, dict) else None)
            if session:
                return {
                    "access_token": getattr(session, "access_token", None),
                    "refresh_token": getattr(session, "refresh_token", None) or refresh_token,
                    "user": user,
                }
        except Exception:
            continue
    return None

def restore_session_from_cookies() -> bool:
    at = (cookies.get("access_token") or "").strip()
    rt = (cookies.get("refresh_token") or "").strip()
    email = (cookies.get("user_email") or "").strip()

    if not at and not rt:
        return False

    # If we only have RT (or AT seems invalid), try to refresh.
    if (not at) and rt:
        refreshed = _best_effort_refresh_with_rt(rt)
        if refreshed and refreshed.get("access_token"):
            at = refreshed["access_token"] or ""
            rt = refreshed.get("refresh_token") or rt
            cookies["access_token"] = at
            cookies["refresh_token"] = rt
            try:
                cookies.save()
            except Exception:
                pass
            st.session_state["user"] = refreshed.get("user") or {"email": email}
    else:
        # Best effort user info: keep UI logged-in even if get_user fails
        if email:
            st.session_state["user"] = {"email": email}

    if at:
        st.session_state["access_token"] = at
    if rt:
        st.session_state["refresh_token"] = rt

    # Validate/fetch user (best effort, never blocks persistence)
    if supabase and at:
        try:
            res = supabase.auth.get_user(at)
            u = getattr(res, "user", None) or (res.get("user") if isinstance(res, dict) else None)
            if u:
                st.session_state["user"] = u
        except Exception:
            pass

    return bool(st.session_state.get("access_token"))


def is_logged_in() -> bool:
    return bool(st.session_state.get("access_token")) and bool(st.session_state.get("user"))

def do_logout():
    try:
        if supabase:
            try:
                supabase.auth.sign_out()
            except Exception:
                pass
    except Exception:
        pass

    try:
        cookies["access_token"] = ""
        cookies["refresh_token"] = ""
        cookies["user_email"] = ""
        cookies.save()
    except Exception:
        pass

    for k in list(st.session_state.keys()):
        if k in ("page",):
            continue
        st.session_state.pop(k, None)
    st.session_state["page"] = "home"
    st.rerun()

# ============================================================
# ✅ Top Menu (common for training pages)
# ============================================================
def top_menu(active: str | None = None) -> str | None:
    items = [
        ("home", "홈"),
        ("word", "단어"),
        ("kanji", "한자"),
        ("talk", "회화"),
        ("mypage", "마이페이지"),
        ("logout", "로그아웃"),
    ]
    cols = st.columns(len(items))
    clicked = None
    for i, (key, label) in enumerate(items):
        disabled = (active == key)
        with cols[i]:
            if st.button(label, key=f"topnav_{key}", use_container_width=True, disabled=disabled):
                clicked = key
    return clicked

def handle_menu(clicked: str):
    if clicked == "logout":
        do_logout()
    elif clicked == "home":
        st.session_state["page"] = "home"
        st.rerun()
    elif clicked == "word":
        st.session_state["page"] = "word"
        st.session_state["entry_target"] = "quiz"
        st.rerun()
    elif clicked == "kanji":
        st.session_state["page"] = "kanji"
        st.session_state["entry_target"] = "quiz"
        st.rerun()
    elif clicked == "talk":
        st.session_state["page"] = "talk"
        st.rerun()
    elif clicked == "mypage":
        st.session_state["page"] = "mypage"
        st.rerun()

# ============================================================
# ✅ Embedded apps (single-file integration)
# ============================================================
_WORD_APP_B64 = ""
_KANJI_APP_B64 = ""

def _exec_embedded_app(src_b64: str, entry: str = "quiz"):
    # Patch cookie manager inside embedded code to avoid duplicate components.
    import streamlit_cookies_manager as scm

    class HubCookies(dict):
        def ready(self) -> bool:
            return True
        def get(self, key, default=None):
            if key in st.session_state:
                return st.session_state.get(key) or default
            return super().get(key, default)
        def __setitem__(self, key, value):
            st.session_state[key] = value
            return super().__setitem__(key, value)
        def save(self):
            return None

    scm.EncryptedCookieManager = lambda *a, **k: HubCookies()

    # Patch set_page_config to no-op (embedded apps must not change shell)
    st.set_page_config = lambda *a, **k: None

    # Hide duplicate buttons from embedded apps (mypage/logout)
    orig_button = st.button
    HIDE_SUBSTR = ("마이페이지", "로그아웃", "로그아웃하기", "My Page", "Logout", "ログアウト", "マイページ")
    def wrapped_button(label, *args, **kwargs):
        try:
            if isinstance(label, str) and any(s in label for s in HIDE_SUBSTR):
                return False
        except Exception:
            pass
        return orig_button(label, *args, **kwargs)
    st.button = wrapped_button

    # Force entry
    st.session_state["page"] = entry
    st.session_state["entry_target"] = entry
    st.session_state["quiz_entry"] = True

    # Make sure tokens are accessible
    if st.session_state.get("access_token"):
        st.session_state["access_token"] = st.session_state["access_token"]
    if st.session_state.get("refresh_token"):
        st.session_state["refresh_token"] = st.session_state["refresh_token"]

    src = base64.b64decode(src_b64.encode("ascii")).decode("utf-8", errors="ignore")
    g = {
        "__name__": "__main__",
        "__file__": "<embedded>",
    }
    exec(compile(src, "<embedded>", "exec"), g, g)

