# ✅ Screens
# ============================================================
def render_login():
    hub_header()
    if not supabase:
        st.error("Supabase 설정이 없습니다. secrets에 SUPABASE_URL / SUPABASE_ANON_KEY를 설정해주세요.")
        return

    st.session_state.setdefault("auth_mode", "login")
    c1, c2 = st.columns(2)
    with c1:
        if st.button("로그인", use_container_width=True):
            st.session_state["auth_mode"] = "login"
    with c2:
        if st.button("회원가입", use_container_width=True):
            st.session_state["auth_mode"] = "signup"

    mode = st.session_state["auth_mode"]
    hr()

    email = st.text_input("이메일", key="auth_email")
    pw = st.text_input("비밀번호", type="password", key="auth_pw")

    if mode == "login":
        if st.button("로그인하기", use_container_width=True):
            try:
                res = supabase.auth.sign_in_with_password({"email": email, "password": pw})
                session = getattr(res, "session", None) or (res.get("session") if isinstance(res, dict) else None)
                user = getattr(res, "user", None) or (res.get("user") if isinstance(res, dict) else None)
                if not session:
                    st.error("로그인에 실패했습니다.")
                    return

                st.session_state["user"] = user or {"email": email}
                st.session_state["access_token"] = session.access_token
                st.session_state["refresh_token"] = session.refresh_token

                cookies["access_token"] = session.access_token
                cookies["refresh_token"] = session.refresh_token
                cookies["user_email"] = email
                cookies.save()

                st.session_state["page"] = "home"
                st.rerun()
            except Exception as e:
                st.error(f"로그인 오류: {e}")
    else:
        if st.button("회원가입하기", use_container_width=True):
            try:
                supabase.auth.sign_up({"email": email, "password": pw})
                st.success("회원가입 요청이 처리되었습니다. 이메일 인증이 필요한 경우 메일을 확인해주세요.")
            except Exception as e:
                st.error(f"회원가입 오류: {e}")

def render_home():
    hub_header()

    if is_logged_in():
        u = st.session_state.get("user") or {}
        email = getattr(u, "email", None) or (u.get("email") if isinstance(u, dict) else "")
        if email:
            st.caption(f"로그인됨: {email}")

    if st.button("📘 단어 훈련", use_container_width=True):
        st.session_state["page"] = "word"
        st.session_state["entry_target"] = "quiz"
        st.rerun()

    if st.button("✍️ 한자 훈련", use_container_width=True):
        st.session_state["page"] = "kanji"
        st.session_state["entry_target"] = "quiz"
        st.rerun()

    if st.button("🗣 회화 훈련", use_container_width=True):
        st.session_state["page"] = "talk"
        st.rerun()

def render_talk():
    clicked = top_menu(active="talk")
    if clicked:
        handle_menu(clicked)
        return
    slim_header("회화 훈련", "준비중")
    st.info("회화 기능은 준비 중입니다.")

def render_mypage():
    clicked = top_menu(active="mypage")
    if clicked:
        handle_menu(clicked)
        return
    slim_header("마이페이지")
    st.info("마이페이지는 준비 중입니다.")
    st.caption("여기에 학습 기록, 오답노트 요약, 구독 상태 등을 붙일 수 있습니다.")

def render_router():
    page = st.session_state.get("page", "home")

    if page == "home":
        render_home()
        return

    if not is_logged_in():
        st.session_state["page"] = "home"
        st.rerun()

    # Common menu for all training pages
    clicked = top_menu(active=page)
    if clicked:
        handle_menu(clicked)
        return

    entry = st.session_state.get("entry_target", "quiz")

    if page == "word":
        slim_header("단어 훈련")
        _exec_embedded_app(_WORD_APP_B64, entry=entry)
        return

    if page == "kanji":
        slim_header("한자 훈련")
        _exec_embedded_app(_KANJI_APP_B64, entry=entry)
        return

    if page == "talk":
        render_talk()
        return

    if page == "mypage":
        render_mypage()
        return

    st.session_state["page"] = "home"
    st.rerun()

# ============================================================
# ✅ Entry
# ============================================================
try:
    if not is_logged_in():
        restore_session_from_cookies()
    if not is_logged_in():
        render_login()
    else:
        render_router()
except Exception:
    st.error("예상치 못한 오류가 발생했습니다.")
    st.code(traceback.format_exc())
